INSERT INTO ontology_documents (id, name, version, source_file, default_language, usecase, group_key) VALUES
  ('5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Nuclear Decommissioning Test Ontology', '0.2.0-test', 'decommissioning_ontology_import_large.json', 'en', 'A larger test ontology for importing modular decommissioning concepts, competency questions, examples, translations, notes, relation attributes, and extraction-aligned facts.', 'shared');
INSERT INTO ontology_modules (id, ontology_id, name, description) VALUES
  ('3bd7afc2-74de-5869-a4e2-01dedf0e8116', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Facility and Asset Context', 'Models the nuclear facility, reactor units, buildings, systems, and components relevant for decommissioning.'),
  ('27c354b5-0ea6-5c28-afcf-67fc750cedf6', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Regulatory Compliance and Permits', 'Models authorities, permits, legal requirements, inspections, and regulatory reports.'),
  ('bdef88a3-b77a-599a-ab5f-b489e0b058b2', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Decommissioning Planning and Execution', 'Models projects, phases, decommissioning steps, work packages, milestones, contractors, and dependencies.'),
  ('7c464371-19ad-5e07-8e4e-0fb7f2ab95f3', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Radiological Characterization and Safety', 'Models radiological inventories, contamination zones, dose constraints, safety measures, and monitoring programs.'),
  ('bf6ea74e-b71f-5874-a148-b76376943176', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Waste Management and Clearance', 'Models waste streams, waste packages, clearance measurements, transport campaigns, and disposal facilities.');
