INSERT INTO ontology_notes (id, ontology_id, body, author_name, sort_order, target_ontology_id, target_module_id, target_class_id, target_relation_id, target_attribute_id, target_relation_attribute_id, target_cq_id) VALUES
  ('881ac507-3949-5e8a-a43e-13516204aef5', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'This ontology is intentionally broad and cross-module to test import, graph rendering, extraction alignment, provenance, and relation metadata handling.', 'ChatGPT', 1, '5008c4d1-7937-535e-8bb5-c47d306b19ec', NULL, NULL, NULL, NULL, NULL, NULL),
  ('cdf0cf3a-c142-5cc6-8e80-88a63eaf9957', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Regulatory concepts are separated from execution concepts but connected through permits, reports, inspections, and constraints.', 'ChatGPT', 2, NULL, '27c354b5-0ea6-5c28-afcf-67fc750cedf6', NULL, NULL, NULL, NULL, NULL),
  ('5025e9bd-904f-5e26-abd5-ebce56297d4e', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Waste handling is modeled beyond a simple waste class to test package, measurement, transport, and destination relations.', 'ChatGPT', 3, NULL, 'bf6ea74e-b71f-5874-a148-b76376943176', NULL, NULL, NULL, NULL, NULL),
  ('24d30103-9e35-59a4-a0b0-b294f541b934', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'A step is the central planning object and deliberately connects to regulatory approval, safety constraints, and waste generation.', 'ChatGPT', 4, NULL, NULL, '2bfffb55-23d0-557a-878a-41ecf19028ac', NULL, NULL, NULL, NULL),
  ('426bff67-c217-5d74-b9b6-c55ff9b43d14', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Self-relations should be supported by the importer and graph UI; this relation tests that case.', 'ChatGPT', 5, NULL, NULL, NULL, 'c8fe4abb-537f-5200-b4da-716ca888481c', NULL, NULL, NULL),
  ('32e92cde-7562-5020-b00a-073b93e23ede', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'The legalBasis relation attribute is required because issuance should be traceable to a normative authority.', 'ChatGPT', 6, NULL, NULL, NULL, NULL, NULL, 'bac2ffdc-4acb-5558-bd8f-dd8bd7b2a933', NULL),
  ('627f8527-941a-581f-9164-10fade3bf136', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'This CQ is intentionally cross-module: planning step to waste stream.', 'ChatGPT', 7, NULL, NULL, NULL, NULL, NULL, NULL, 'f875042b-b7ad-5eb2-a6df-db02252da32f'),
  ('d527d993-b744-5d69-b7d1-bc7feede6d9a', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Module purpose: Models the nuclear facility, reactor units, buildings, systems, and components relevant for decommissioning.', 'ChatGPT', 10, NULL, '3bd7afc2-74de-5869-a4e2-01dedf0e8116', NULL, NULL, NULL, NULL, NULL),
  ('9e1549c6-fec0-5572-9994-420b90e397d3', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Module purpose: Models authorities, permits, legal requirements, inspections, and regulatory reports.', 'ChatGPT', 11, NULL, '27c354b5-0ea6-5c28-afcf-67fc750cedf6', NULL, NULL, NULL, NULL, NULL),
  ('c38d1247-5877-5443-8337-1a624ee79bc7', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Module purpose: Models projects, phases, decommissioning steps, work packages, milestones, contractors, and dependencies.', 'ChatGPT', 12, NULL, 'bdef88a3-b77a-599a-ab5f-b489e0b058b2', NULL, NULL, NULL, NULL, NULL),
  ('c97671e7-decf-52ef-8992-145d97fb3799', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Module purpose: Models radiological inventories, contamination zones, dose constraints, safety measures, and monitoring programs.', 'ChatGPT', 13, NULL, '7c464371-19ad-5e07-8e4e-0fb7f2ab95f3', NULL, NULL, NULL, NULL, NULL),
  ('82a5e649-0c40-5ac4-a90f-b1d442f6a895', '5008c4d1-7937-535e-8bb5-c47d306b19ec', 'Module purpose: Models waste streams, waste packages, clearance measurements, transport campaigns, and disposal facilities.', 'ChatGPT', 14, NULL, 'bf6ea74e-b71f-5874-a148-b76376943176', NULL, NULL, NULL, NULL, NULL);
